from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1]
d=json.loads((R/'catalog/apps_catalog.json').read_text())
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Atlas OS · Open-Source Garden</title><style>
:root{font-family:system-ui,-apple-system,'Segoe UI',sans-serif;color-scheme:dark;background:#081923;color:#ebf4f0}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 10% 0%,#123e46,#07151f 59%);min-height:100vh}.wrap{max-width:1240px;margin:auto;padding:25px 20px 90px}header{display:flex;align-items:center;justify-content:space-between;gap:18px}h1{font-weight:650;letter-spacing:-.035em;font-size:clamp(1.6rem,4vw,2.8rem);margin:16px 0 10px}.eyebrow{color:#90e5d5;letter-spacing:.13em;font-size:11px;font-weight:700}.muted{color:#a9bec4}.subtitle{max-width:760px;line-height:1.5}.pill{display:inline-block;border:1px solid #4a7778;border-radius:50px;padding:7px 11px;color:#b9d9d7;font-size:12px}.layout{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(0,.9fr);gap:17px;margin-top:24px}section,.panel{border:1px solid #35535b;background:linear-gradient(145deg,#122b35e8,#10232ce8);border-radius:20px;padding:20px;box-shadow:0 10px 35px #0002}button,select,input{font:inherit}button{cursor:pointer;color:#e9f9f3;background:#1c4047;border:1px solid #56777c;border-radius:12px;padding:9px 13px}button:focus-visible,select:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid #8be1b7;outline-offset:2px}button.active{background:#216d61;border-color:#81cfbb}button:hover{background:#2a5c5d}input,select{background:#102a33;color:#edfaf6;border:1px solid #547379;border-radius:11px;padding:10px;min-width:0}input{width:100%}.controls{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0 18px}.profiles{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:12px}label{display:block;color:#b5d1d2;font-size:12px;margin:12px 0 5px}.list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.app{padding:13px 14px;text-align:left;background:#15333d;min-height:94px}.app strong,.app span{display:block}.app small{display:block;font-size:11px;color:#a1bdc4;margin-top:8px}.app .tag{margin-top:5px;color:#9ee5cf;font-size:12px}.app.selected{border-color:#c2f7e8;background:#1c4750}.stats{display:flex;gap:6px;flex-wrap:wrap;margin:16px 0}.stat{border-radius:9px;background:#133c43;padding:8px 12px;color:#caede6;font-size:12px}aside{position:sticky;top:18px;height:max-content}.detail h2{margin:0 0 7px;font-size:1.5rem}.detail p{margin:10px 0;color:#bed1d2;line-height:1.5}.kv{display:flex;justify-content:space-between;gap:10px;border-top:1px solid #2e565a;padding:10px 0;font-size:12px}.kv strong{font-weight:580;text-align:right;overflow-wrap:anywhere}.notice{border-left:3px solid #a0d9c8;padding:10px;background:#173740;border-radius:6px;color:#d7edec;font-size:12px;line-height:1.6}a{color:#8bd9bd}.dialog{display:none;margin-top:12px;background:#0b2732;border:1px solid #5a8582;border-radius:12px;padding:13px;line-height:1.55;font-size:12px}.dialog.visible{display:block}.dialog h3{margin:0 0 6px;font-size:1rem}.hero{padding-top:15px}.hero-circles{display:flex;gap:8px;justify-content:flex-end}.circle{width:12px;height:12px;border-radius:50%;background:#73c7aa;box-shadow:0 0 12px #73c7aa6e}.circle:nth-child(2){background:#6ca9cf}.circle:nth-child(3){background:#edbf82}.small{font-size:11px}.gate{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.gate button{font-size:12px}.footer{padding:30px 0;color:#7a9ca0;font-size:11px}.visually-hidden{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:780px){.layout{grid-template-columns:1fr}.list{grid-template-columns:1fr 1fr}aside{position:static}section{padding:15px}.wrap{padding:14px 12px 60px}}@media(max-width:430px){.list{grid-template-columns:1fr}.app{min-height:76px}}@media(prefers-reduced-motion:no-preference){button{transition:background .15s}}
</style></head><body><div class="wrap"><header><div><span class="eyebrow">ATLAS OS · NATIVE APPLICATIONS</span><h1>Open-Source Garden</h1><p class="subtitle muted">A calm home for useful, source-credited software. Familiar tools, native Atlas intents, and no mandatory subscription bundle.</p></div><div class="hero-circles" aria-hidden="true"><span class="circle"></span><span class="circle"></span><span class="circle"></span></div></header>
<div class="stats"><span class="stat" id="statTotal">37 upstream candidates</span><span class="stat" id="statPinned">36 source revisions pinned</span><span class="stat">0 silently installed</span><span class="stat">No account required for offline apps</span></div>
<div class="layout"><main><section><div class="eyebrow">DISCOVER BY PURPOSE</div><div class="profiles" id="profiles" role="group" aria-label="Choose software profile"></div><label for="search">Search applications</label><input id="search" type="search" autocomplete="off" placeholder="Documents, photo, video, privacy, games..." aria-label="Search applications"><div class="controls"><button id="all">All apps</button><button id="stable">Established candidates</button><button id="experimental">Experimental ArtCraft</button></div><div id="resultStatus" class="muted small" aria-live="polite"></div><div class="list" id="appList" aria-label="Application candidates"></div></section></main>
<aside class="panel"><div class="eyebrow">SOURCE & PERMISSION PREVIEW</div><div class="detail"><h2 id="name">Choose an application</h2><p id="description">This is an offline, read-only review prototype; no app installer or identity broker is running.</p><div class="kv"><span>Upstream</span><strong id="upstream">Not selected</strong></div><div class="kv"><span>Revision</span><strong id="commit">Not selected</strong></div><div class="kv"><span>License metadata</span><strong id="license">Not selected</strong></div><div class="kv"><span>Release readiness</span><strong id="readiness">Not installed</strong></div><div class="kv"><span>Identity</span><strong id="account">No automatic login</strong></div><div class="notice" id="notice">Exact source commits are NOT verified installation packages. Apps stay separate and consent-scoped.</div><div class="gate"><button id="previewInstall" disabled>Preview install plan</button><button id="previewAccount" disabled>Identity boundary</button><button id="previewPrivacy" disabled>Privacy controls</button></div><div class="dialog" id="dialog" aria-live="polite"></div></div></aside></div><div class="footer">Original Atlas kernel ≠ Linux compatibility sandbox ≠ source app. CANON review is not adoption. Protected Palace, Quiet and voluntary modes are never input to this Work catalog. No network requests, telemetry, downloads, credentials or real installations occur on this page.</div>
</div><script type="application/json" id="atlasCatalog">__CATALOG__</script><script>
'use strict';const data=JSON.parse(document.getElementById('atlasCatalog').textContent);const apps=data.apps;let profile='all',type='all',selection=null;
const $=x=>document.getElementById(x);const display=a=>a.title+' — '+a.category;
const profiles=['all','everyday','creative','games','privacy','team','labs','infrastructure'];
for(const p of profiles){const b=document.createElement('button');b.textContent=p==='all'?'Everything':p[0].toUpperCase()+p.slice(1);b.dataset.profile=p;b.addEventListener('click',()=>{profile=p;if(p==='all')type='all';render()});$('profiles').append(b)}
function render(){for(const b of $('profiles').querySelectorAll('button')){const active=b.dataset.profile===profile;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))}
 const search=$('search').value.trim().toLowerCase();const visible=apps.filter(a=>(profile==='all'||a.profile===profile)&&(type==='all'||(type==='stable'&&a.maturity==='established_candidate')||(type==='experimental'&&a.family==='ArtCraft'))&&[a.title,a.category,a.family,a.id].some(x=>x.toLowerCase().includes(search)));$('appList').replaceChildren();for(const a of visible){const b=document.createElement('button');b.className='app'+(selection?.id===a.id?' selected':'');b.dataset.app=a.id;b.setAttribute('aria-label','Inspect '+a.title);const t=document.createElement('strong');t.textContent=a.title;const s=document.createElement('span');s.className='tag';s.textContent=a.family+' · '+a.profile;const d=document.createElement('small');d.textContent=a.category+' · '+(a.maturity==='experimental'?'Early-stage / opt-in':a.maturity==='upstream_binary_pin_pending'?'Release pin pending':'Candidate, review pending');b.append(t,s,d);b.onclick=()=>select(a);$('appList').append(b)}$('resultStatus').textContent=visible.length+' of '+apps.length+' candidates shown';$('statTotal').textContent=apps.length+' upstream candidates';$('statPinned').textContent=apps.filter(a=>a.source_revision).length+' source revisions pinned'}
function select(a){selection=a;$('name').textContent=a.title;$('description').textContent=a.category+' · '+a.family;$('upstream').textContent=a.upstream.replace('https://github.com/','');$('commit').textContent=a.source_revision?a.source_revision.slice(0,12)+'…':'Not pinned — HOLD';$('license').textContent=a.metadata_license+' · '+a.license_review;$('readiness').textContent=a.maturity==='experimental'?'EARLY-STAGE / OPT-IN':'CANDIDATE — NOT INSTALLED';$('account').textContent=a.account==='none'?'Offline, no service login':a.account==='external'?'External provider consent needed':'Optional provider support';$('notice').textContent=a.maturity==='experimental'?'ArtCraft is early-stage: test in a sandbox and keep your original documents. No automatic bundled installation.':'A source commit is not an independently signed release. Atlas must check package hash, license, consent, permission, rollback.';for(const id of ['previewInstall','previewAccount','previewPrivacy'])$(id).disabled=false;$('dialog').className='dialog';render()}
function show(title,description){$('dialog').replaceChildren();const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=description;$('dialog').append(h,p);$('dialog').className='dialog visible'}
$('previewInstall').onclick=()=>{if(!selection)return;show('Install plan — HOLD, not executed',selection.title+' requires its exact binary/package digest, signature, compatible sandbox/driver inventory, per-app license review, opt-in where experimental, and explicit human approval. This prototype cannot install applications.')};
$('previewAccount').onclick=()=>{if(!selection)return;show('One device sign-in ≠ universal service login',selection.account==='none'?selection.title+' runs locally without an external service login.':selection.title+' must explicitly support a standards-based sign-in or secure app-specific token. Device biometrics unlock scoped local credentials; the OS cannot silently log in to unrelated websites.')} ;
$('previewPrivacy').onclick=()=>{if(!selection)return;show('Private by default','Documents via explicit file portal. Untrusted apps have separate sandboxes. No background cloud account. Browser content blockers need visible permissions; VPN is always opt-in. Protected Palace/Quiet data are never copied into Work.')};
$('search').addEventListener('input',render);$('all').onclick=()=>{type='all';render()};$('stable').onclick=()=>{type='stable';render()};$('experimental').onclick=()=>{type='experimental';render()};
render();select(apps.find(a=>a.id==='libreoffice')||apps[0]);
</script></body></html>'''
# Avoid HTML script termination in embedded data
payload=json.dumps({'apps':d['apps']},ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
(R/'web/ATLAS_OS_OPEN_SOURCE_GARDEN.html').write_text(page.replace('__CATALOG__',payload))
print('ui built',(R/'web/ATLAS_OS_OPEN_SOURCE_GARDEN.html').stat().st_size)
